# Toy triage helper modelled on Chromium's severity guidelines
def severity(process, needs_bad_renderer, effect):
    if effect == "code_exec":
        if process == "renderer":
            return "High: code runs inside the sandbox"
        if needs_bad_renderer:
            return "High: sandbox escape, needs a renderer bug first"
        return "Critical: privileged process reached from a web page"
    if effect == "cross_site_data":
        return "High: one site reads another site's data"
    return "Medium or Low: depends on scope"

bugs = [
    ("JIT type confusion", "renderer", False, "code_exec"),
    ("Broker trusts a renderer handle", "browser", True, "code_exec"),
    ("Browser overflow from page data", "browser", False, "code_exec"),
    ("Two sites share one renderer", "renderer", False, "cross_site_data"),
]
for name, proc, pre, effect in bugs:
    print(f"{name:33} {severity(proc, pre, effect)}")

