# Toy browser-side storage service. Each renderer connection is created
# by the browser, which knows which site the renderer is locked to.
STORE = {"https://bank.example": "balance=1200",
         "https://evil.example": "nothing"}

class BadMessage(Exception):
    pass

class VulnerableStorageHost:
    def __init__(self, locked_site):
        self.locked_site = locked_site
    def read(self, origin):                  # origin comes from the renderer
        return STORE[origin]

class FixedStorageHost:
    def __init__(self, locked_site):
        self.locked_site = locked_site       # set by the browser, not the renderer
    def read(self):                          # no origin parameter at all
        return STORE[self.locked_site]

class CheckedStorageHost(FixedStorageHost):
    def read_for(self, origin):              # if an origin must cross IPC
        if origin != self.locked_site:
            raise BadMessage(f"kill renderer: asked for {origin}")
        return STORE[origin]

# A compromised renderer locked to evil.example sends a forged origin.
print("vulnerable:", VulnerableStorageHost("https://evil.example").read("https://bank.example"))
print("fixed:     ", FixedStorageHost("https://evil.example").read())
try:
    CheckedStorageHost("https://evil.example").read_for("https://bank.example")
except BadMessage as e:
    print("checked:   ", e)

# Toy model of a broker relaying OS handles for a sandboxed renderer.
# Toy OS rule: small negative values are "pseudo handles" that mean the
# CALLER's own process (-1) or own thread (-2), not the sender's.
def os_duplicate(caller, source_table, value):
    if value == -1:
        return f"process:{caller}"
    if value == -2:
        return f"thread:{caller}"
    return source_table[value]

renderer_handles = {4: "file:upload.png (read-only)"}

def relay_vulnerable(value):
    if value == -1:                        # only one pseudo value blocked
        raise ValueError("rejected -1")
    return os_duplicate("browser", renderer_handles, value)

def relay_fixed(value):
    if value not in renderer_handles:      # only real handles the sender owns
        raise ValueError(f"bad message: {value}, terminate renderer")
    return os_duplicate("browser", renderer_handles, value)

for relay in (relay_vulnerable, relay_fixed):
    for value in (4, -1, -2):
        try:
            print(f"{relay.__name__:17} {value:>2} -> {relay(value)}")
        except ValueError as e:
            print(f"{relay.__name__:17} {value:>2} -> {e}")

/* Toy browser-side code converting a bitmap that a renderer sent. */
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
enum Format { RGB565 = 2, ARGB8888 = 4, RGBA_F16 = 8 };  /* bytes/pixel */

static int output_bpp(enum Format f) {
  switch (f) {
    case RGB565: return 2;
    case ARGB8888: return 4;
    default: assert(!"unsupported"); /* gone when built with -DNDEBUG */
             return 4;                /* silent fallback */
  }
}

static int convert_vulnerable(const void *px, int w, int h, enum Format f) {
  unsigned char *out = malloc((size_t)w * h * output_bpp(f));
  memcpy(out, px, (size_t)w * h * f);   /* copies INPUT size */
  free(out);
  return 1;
}

static int convert_fixed(const void *px, int w, int h, enum Format f) {
  if (f != RGB565 && f != ARGB8888) return 0;   /* reject, report bad IPC */
  size_t n = (size_t)w * h * output_bpp(f);
  if (n != (size_t)w * h * f) return 0;         /* sizes must agree */
  unsigned char *out = malloc(n);
  memcpy(out, px, n);
  free(out);
  return 1;
}

int main(int argc, char **argv) {
  static unsigned char px[4 * 4 * 8];           /* 4x4 RGBA_F16 from renderer */
  printf("fixed, ARGB8888: %d\n", convert_fixed(px, 4, 4, ARGB8888));
  printf("fixed, RGBA_F16: %d\n", convert_fixed(px, 4, 4, RGBA_F16));
  fflush(stdout);
  if (argc > 1) printf("vulnerable, F16: %d\n", convert_vulnerable(px, 4, 4, RGBA_F16));
  return 0;
}

# Toy engine: a shape maps property -> (slot, kind). Slots hold raw
# numbers; kind says whether the number is a value or a heap address.
HEAP = {0x1000: "Array(len=2)", 0x2000: "another object's bytes"}

class Obj:
    def __init__(self):
        self.shape = {"a": (0, "num"), "b": (1, "obj")}
        self.slots = [7, 0x1000]

def relayout(o):              # page script that runs inside the store
    o.shape = {"b": (0, "obj"), "a": (1, "num")}
    o.slots = [o.slots[1], o.slots[0]]

def store(o, name, raw, kind, callback, recheck):
    slot, k = o.shape[name]            # look up and check kind once
    if k != kind:
        raise TypeError("kind mismatch")
    callback(o)                        # user code runs here
    if recheck:                        # the fix: look up again
        slot, k = o.shape[name]
        if k != kind:
            raise TypeError("kind mismatch")
    o.slots[slot] = raw

def load_b(o):                         # optimized code trusts the shape
    slot, kind = o.shape["b"]
    return HEAP.get(o.slots[slot], "?") if kind == "obj" else o.slots[slot]

for recheck in (False, True):
    o = Obj()
    store(o, "a", 0x2000, "num", relayout, recheck)
    print(f"recheck={recheck!s:5} slots={[hex(s) for s in o.slots]} b -> {load_b(o)}")

/* Toy prefix-code lookup table, sized for the worst VALID input. */
#include <stdio.h>
#include <stdlib.h>
#define ROOT_BITS 3
#define TABLE_SIZE (1 << ROOT_BITS)

/* A symbol with code length L fills 2^(ROOT_BITS-L) table slots. */
static int build_vulnerable(const int *len, int n, unsigned char *t) {
  int pos = 0;
  for (int s = 0; s < n; s++)
    for (int k = 0; k < 1 << (ROOT_BITS - len[s]); k++)
      t[pos++] = (unsigned char)s;   /* writes before validating */
  return pos == TABLE_SIZE;          /* checked only at the end */
}

static int slots_needed(const int *len, int n) {
  int total = 0;
  for (int s = 0; s < n; s++) total += 1 << (ROOT_BITS - len[s]);
  return total;
}

static int build_fixed(const int *len, int n, unsigned char *t) {
  if (slots_needed(len, n) != TABLE_SIZE) return 0;  /* pass 1 */
  return build_vulnerable(len, n, t);                /* pass 2 */
}

int main(int argc, char **argv) {
  int valid[] = {1, 2, 3, 3};   /* 4 + 2 + 1 + 1 = 8 slots */
  int bad[]   = {1, 1, 2, 2};   /* 4 + 4 + 2 + 2 = 12 slots */
  unsigned char *t = malloc(TABLE_SIZE);
  printf("fixed, valid lengths: %d\n", build_fixed(valid, 4, t));
  printf("fixed, bad lengths:   %d\n", build_fixed(bad, 4, t));
  if (argc > 1)
    printf("vulnerable, bad:      %d\n", build_vulnerable(bad, 4, t));
  free(t);
  return 0;
}

# CVE-2023-4863: days from the upstream fix (libwebp commit, 7 Sep 2023)
# to each downstream release, from the public advisories and release notes.
from datetime import date

upstream = date(2023, 9, 7)
releases = {
    "Chrome 116.0.5845.187": date(2023, 9, 11),
    "Firefox 117.0.1":       date(2023, 9, 12),
    "Electron 26.2.1":       date(2023, 9, 12),
    "libwebp 1.3.2 tag":     date(2023, 9, 13),
    "Electron 22.3.24":      date(2023, 9, 13),
}
for name, day in releases.items():
    print(f"{name:22} +{(day - upstream).days} days")

# Which installed builds still lack the fix? (synthetic inventory)
def ver(s):
    return tuple(int(p) for p in s.split("."))

FIXED_CHROMIUM = {116: "116.0.5845.187"}   # first fixed build per major
inventory = {"laptop-17 Chrome": "116.0.5845.179",
             "laptop-22 Chrome": "116.0.5845.188",
             "ChatApp (Electron 25)": "114.0.5735.289",
             "Kiosk (old WebView)": "112.0.5615.136"}
for host, v in inventory.items():
    major = ver(v)[0]
    fixed = FIXED_CHROMIUM.get(major)
    if fixed and ver(v) >= ver(fixed):
        status = "patched"
    elif fixed:
        status = f"VULNERABLE, update to {fixed}+"
    else:
        status = "no fixed build listed for this major: check the vendor"
    print(f"{host:23} Chromium {v:16} {status}")

# Audit exported browser policies and extensions per device (synthetic).
fleet = {
    "dev-laptop-04": {"policies": {"SitePerProcess": True,
                                   "ExtensionInstallBlocklist": ["*"]},
                      "extensions": {"pwmanager": ["https://*/*"]}},
    "sales-laptop-11": {"policies": {"SitePerProcess": False},
                        "extensions": {"coupon-finder": ["<all_urls>"],
                                       "pwmanager": ["https://*/*"]}},
    "kiosk-02": {"policies": {"DefaultJavaScriptJitSetting": 2,
                              "ExtensionInstallBlocklist": ["*"]},
                 "extensions": {}},
}
ALLOWED = {"pwmanager"}           # reviewed extensions only

for host, d in fleet.items():
    p, findings = d["policies"], []
    if "*" not in p.get("ExtensionInstallBlocklist", []):
        findings.append("no deny-by-default extension policy")
    for ext, hosts in d["extensions"].items():
        if ext not in ALLOWED:
            findings.append(f"unreviewed extension {ext} on {hosts}")
    if p.get("SitePerProcess") is False:
        findings.append("site isolation switched off by policy")
    if p.get("DefaultJavaScriptJitSetting") == 2:
        findings.append("JIT blocked (hardened, slower)")
    print(host, "->", "; ".join(findings) or "baseline met")
